ALTER TABLE "screenshot" ADD COLUMN "source" text DEFAULT 'browser' NOT NULL;--> statement-breakpoint
-- Give the built-in Computer Use agent its tools if it is still empty.
UPDATE "agent" SET "tools" = ARRAY['computer.start','computer.screenshot','computer.click','computer.move','computer.drag','computer.scroll','computer.type','computer.key','computer.wait','computer.stop'], "permissions" = ARRAY['EXECUTE'], "description" = 'Controls the computer''s desktop directly: mouse, keyboard and screen. Use for desktop applications, the file manager, IDEs and other graphical interfaces that are not web pages.', "instructions" = 'You are a desktop automation specialist. Start with computer.start to see the screen, then work in small, deliberate steps: look at each screenshot, decide one action, take it, and look again. Click a field before typing. Use computer.wait after launching apps or triggering slow actions. Before anything destructive or irreversible (deleting files, sending messages, making purchases), stop and ask the user. Report what you did and what is on screen.' WHERE "builtin" AND "slug" = 'computer-use' AND cardinality("tools") = 0;
